parameters.jsCode:
const zone = 'America/Vancouver';
const now = DateTime.now().setZone(zone);
const weekAgo = now.minus({ days: 7 });

function getField(row, name) {
  const key = Object.keys(row).find(k => k.trim().toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : row[key];
}

function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone }).plus({ days: v });
  }
  const s = String(v).trim();
  const formats = ['M/d/yyyy H:mm:ss', 'M/d/yyyy', 'yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd', 'd/M/yyyy H:mm:ss', 'd/M/yyyy'];
  let d = DateTime.fromISO(s, { zone });
  for (const f of formats) {
    if (d.isValid) break;
    d = DateTime.fromFormat(s, f, { zone });
  }
  return d.isValid ? d : null;
}

const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const stageCounts = {};
let scoreSum = 0;
let scoreCount = 0;
let addedLast7 = 0;

for (const row of rows) {
  const stage = String(getField(row, 'Stage') || '').trim() || 'Unscreened';
  stageCounts[stage] = (stageCounts[stage] || 0) + 1;
  const scoreRaw = getField(row, 'Score');
  const score = Number(scoreRaw);
  if (scoreRaw !== undefined && scoreRaw !== '' && !isNaN(score)) {
    scoreSum += score;
    scoreCount++;
  }
  const ts = parseDate(getField(row, 'Timestamp'));
  if (ts && ts >= weekAgo && ts <= now) addedLast7++;
}

const ci = (name) => {
  const key = Object.keys(stageCounts).find(k => k.toLowerCase() === name.toLowerCase());
  return key ? stageCounts[key] : 0;
};
const known = ['assessment', 'review', 'rejected', 'unscreened'];
const other = Object.entries(stageCounts).filter(([k]) => !known.includes(k.toLowerCase())).reduce((a, [, v]) => a + v, 0);
const averageScore = scoreCount ? Math.round((scoreSum / scoreCount) * 10) / 10 : 0;
const breakdown = Object.entries(stageCounts).sort((a, b) => b[1] - a[1]).map(([k, v]) => k + ': ' + v).join(', ') || 'none';

return [{ json: {
  date: now.toFormat('yyyy-MM-dd'),
  totalApplications: rows.length,
  addedLast7Days: addedLast7,
  averageScore,
  scoredCandidates: scoreCount,
  assessment: ci('Assessment'),
  review: ci('Review'),
  rejected: ci('Rejected'),
  unscreened: ci('Unscreened'),
  otherStages: other,
  stageBreakdown: breakdown,
} }];

